use core::hint::black_box;
use charlotte_kafka::scram::{Client,Error};
mod support;
use support::{observe,observe_nth};
const USER:&str="ZZZZZZZZ,=user";const PASSWORD:&[u8]=b"ZZZZZZZZ-password";const NONCE:&str="ZZZZZZZZ-nonce";
const CHALLENGE:&[u8]=b"r=ZZZZZZZZ-nonce-server,s=c2FsdA==,i=4096";
#[test]
fn escaped_username_release(){
 let observed=observe(0,0,0,||drop(black_box(Client::new(USER,PASSWORD,NONCE).unwrap())));
 assert!(observed.copy_erased,"escaped username retained: {observed:?}");
}
#[test]
fn nonce_initial_drop(){
 let observed=observe_nth(4,0,0,0,||drop(black_box(Client::new(USER,PASSWORD,NONCE).unwrap())));
 assert!(observed.copy_erased,"nonce retained: {observed:?}");
}
#[test]
fn nonce_challenge_rejection(){
 let observed=observe_nth(4,0,0,0,||{let c=Client::new(USER,PASSWORD,NONCE).unwrap();assert!(matches!(c.receive_server_first(b"malformed"),Err(Error::InvalidServerMessage)));});
 assert!(observed.copy_erased,"rejected nonce retained: {observed:?}");
}
#[test]
fn nonce_successful_transition(){
 let mut final_phase=None;
 let observed=observe_nth(4,0,0,0,||{let c=Client::new(USER,PASSWORD,NONCE).unwrap();final_phase=Some(c.receive_server_first(CHALLENGE).unwrap());});
 assert!(observed.copy_erased,"transition nonce retained: {observed:?}");
 drop(black_box(final_phase));
}
#[test]
fn existing_password_owner_erases(){
 let observed=observe_nth(3,0,0,0,||drop(black_box(Client::new(USER,PASSWORD,NONCE).unwrap())));
 assert!(observed.copy_erased,"password retained: {observed:?}");
 assert_eq!(observed.allocations,4);assert_eq!(observed.copy_releases,1);
}

